def verify_citation(claim: str, chunk_id: str, retrieved_map: dict, nli) -> bool:
    source = retrieved_map.get(chunk_id)
    if not source:
        return False  # ID fabricado por el modelo
    return nli.predict(premise=source.text, hypothesis=claim) == "entailment"
